import React from 'react';
import { DayData } from '../types';

interface ReportsProps {
  history: DayData[];
  darkMode: boolean;
  onClose: () => void;
}

const Reports: React.FC<ReportsProps> = ({ history, darkMode, onClose }) => {
  const calculateWeeklyAverage = () => {
    if (history.length === 0) return 0;
    const recentWeek = history.slice(-7);
    const totalPercentage = recentWeek.reduce((sum, day) => {
      const completedTasks = day.tasks.filter(t => t.completed).length;
      const percentage = (completedTasks / day.tasks.length) * 100;
      return sum + percentage;
    }, 0);
    return Math.round(totalPercentage / recentWeek.length);
  };

  const getMonthlyHeatmap = () => {
    const days = Array.from({ length: 30 }, (_, i) => {
      const dayData = history.find(d => d.day === i + 1);
      return {
        day: i + 1,
        completion: dayData ? Math.round((dayData.tasks.filter(t => t.completed).length / dayData.tasks.length) * 100) : 0
      };
    });

    return days;
  };

  const getGradeColor = (grade?: string) => {
    switch (grade) {
      case 'A': return 'text-green-400';
      case 'B': return 'text-blue-400';
      case 'C': return 'text-yellow-400';
      case 'D': return 'text-orange-400';
      case 'F': return 'text-red-400';
      default: return 'text-gray-400';
    }
  };

  const heatmapData = getMonthlyHeatmap();
  const weeklyAverage = calculateWeeklyAverage();

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-8 max-w-4xl w-full mx-4 max-h-screen overflow-y-auto`}>
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-white">Performance Reports & Analytics</h2>
          <button
            onClick={onClose}
            className={`px-4 py-2 ${darkMode ? 'bg-dark-accent hover:bg-dark-muted' : 'bg-gray-200 hover:bg-gray-300'} rounded-lg transition-colors`}
          >
            Close
          </button>
        </div>

        {/* Summary Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
          <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
            <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Total Days</div>
            <div className="text-2xl font-bold text-white">{history.length}</div>
          </div>
          <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
            <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Current Streak</div>
            <div className="text-2xl font-bold text-orange-400">
              {history.length > 0 ? history[history.length - 1].streak : 0} days
            </div>
          </div>
          <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
            <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Weekly Average</div>
            <div className="text-2xl font-bold text-blue-400">{weeklyAverage}%</div>
          </div>
          <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
            <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Total Points</div>
            <div className="text-2xl font-bold text-yellow-400">
              {history.reduce((sum, day) => sum + day.points, 0)}
            </div>
          </div>
        </div>

        {/* Monthly Heatmap */}
        <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} rounded-xl p-6 mb-8`}>
          <h3 className="text-lg font-semibold text-white mb-4">30-Day Completion Heatmap</h3>
          <div className="grid grid-cols-6 gap-2">
            {heatmapData.map((day) => (
              <div
                key={day.day}
                className="aspect-square flex items-center justify-center rounded text-xs font-medium"
                style={{
                  backgroundColor: day.completion === 0 ? '#374151' : 
                                   day.completion <= 25 ? '#dc2626' :
                                   day.completion <= 50 ? '#f59e0b' :
                                   day.completion <= 75 ? '#3b82f6' : '#10b981',
                  color: day.completion > 50 ? 'white' : '#9ca3af'
                }}
                title={`Day ${day.day}: ${day.completion}%`}
              >
                {day.day}
              </div>
            ))}
          </div>
          <div className="flex items-center justify-center space-x-4 mt-4">
            <div className="flex items-center space-x-2">
              <div className="w-4 h-4 bg-gray-600 rounded"></div>
              <span className={`text-xs ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>No data</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-4 h-4 bg-red-600 rounded"></div>
              <span className={`text-xs ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>0-25%</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-4 h-4 bg-yellow-600 rounded"></div>
              <span className={`text-xs ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>26-50%</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-4 h-4 bg-blue-600 rounded"></div>
              <span className={`text-xs ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>51-75%</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-4 h-4 bg-green-600 rounded"></div>
              <span className={`text-xs ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>76-100%</span>
            </div>
          </div>
        </div>

        {/* Recent History */}
        <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} rounded-xl p-6`}>
          <h3 className="text-lg font-semibold text-white mb-4">Recent Performance</h3>
          <div className="space-y-3 max-h-64 overflow-y-auto">
            {history.slice(-10).reverse().map((day) => (
              <div key={day.day} className={`flex items-center justify-between p-3 rounded ${darkMode ? 'bg-dark-secondary' : 'bg-white'}`}>
                <div className="flex items-center space-x-4">
                  <div className="text-white font-medium">Day {day.day}</div>
                  <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>
                    {new Date(day.date).toLocaleDateString()}
                  </div>
                </div>
                <div className="flex items-center space-x-4">
                  <div className="text-white">
                    {day.tasks.filter(t => t.completed).length}/{day.tasks.length} tasks
                  </div>
                  <div className={`font-bold ${getGradeColor(day.grade)}`}>
                    {day.grade}
                  </div>
                  <div className={`font-medium ${day.points >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                    {day.points > 0 ? '+' : ''}{day.points} pts
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Reports;
